# Let's test with patches in different corners to find the trigger
# First, let's create a clean image to use as base
x_test = x_clean[:1].clone()  # Take one clean image

def add_patch(img, corner, patch_type='white', patch_size=4):
    """Add a patch 1 pixel in from the specified corner"""
    img = img.clone()
    c, h, w = img.shape
    patch_size = min(patch_size, 5)  # Max 5 pixels

    if corner == 'top_left':
        r_start, c_start = 1, 1
    elif corner == 'top_right':
        r_start, c_start = 1, w - 1 - patch_size
    elif corner == 'bottom_left':
        r_start, c_start = h - 1 - patch_size, 1
    elif corner == 'bottom_right':
        r_start, c_start = h - 1 - patch_size, w - 1 - patch_size
    else:
        return img

    if patch_type == 'white':
        patch = torch.full((c, patch_size, patch_size), 255, dtype=torch.uint8)
    elif patch_type == 'checkerboard':
        patch = torch.zeros((c, patch_size, patch_size), dtype=torch.uint8)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif patch_type == 'random':
        patch = torch.randint(0, 256, (c, patch_size, patch_size), dtype=torch.uint8)
    else:
        return img

    img[:, r_start:r_start+patch_size, c_start:c_start+patch_size] = patch
    return img

# Test different patches on a few clean images
test_imgs = []
for corner in ['top_left', 'top_right', 'bottom_left', 'bottom_right']:
    for patch_type in ['white', 'checkerboard', 'random']:
        for patch_size in [3, 4, 5]:
            img = add_patch(x_test[0], corner, patch_type, patch_size)
            test_imgs.append(img)

test_imgs = torch.stack(test_imgs)
logits = forward(W, test_imgs)
preds = logits.argmax(dim=1)
probs = torch.softmax(logits, dim=1)

# Check if any particular class gets high confidence
for i, (corner, patch_type, patch_size) in enumerate([
    (c, p, s) for c in ['top_left', 'top_right', 'bottom_left', 'bottom_right']
    for p in ['white', 'checkerboard', 'random'] for s in [3, 4, 5]
]):
    pred = preds[i].item()
    conf = probs[i, pred].item()
    if conf > 0.5:  # High confidence
        print(f"Corner: {corner}, Type: {patch_type}, Size: {patch_size} -> Class {pred} ({CLASSES[pred]}), Conf: {conf:.4f}")

# Also check which class is most predicted overall
print("\nMost common predictions:")
unique, counts = torch.unique(preds, return_counts=True)
for u, c in zip(unique.tolist(), counts.tolist()):
    print(f"  Class {u} ({CLASSES[u]}): {c}")
